```javascript
const fs = require('fs');

const data = fs.readFileSync(0, 'utf8');
const tokens = data.split(/\s+/);
let idx = 0;

const nextInt = () => parseInt(tokens[idx++], 10);

const S = nextInt();
const T = nextInt();

// Matriz de adjacência compacta (S <= 1000 => no máximo 10^6 bytes)
const adj = new Uint8Array(S * S);

for (let i = 0; i < T; i++) {
  const x = nextInt() - 1;
  const y = nextInt() - 1;
  adj[x * S + y] = 1;
  adj[y * S + x] = 1;
}

const P = nextInt();
let possible = 0;

for (let p = 0; p < P; p++) {
  const N = nextInt();
  let prev = nextInt() - 1;
  let ok = true;
  for (let i = 1; i < N; i++) {
    const cur = nextInt() - 1;
    if (ok && !adj[prev * S + cur]) {
      ok = false;
    }
    prev = cur;
  }
  if (ok) possible++;
}

process.stdout.write(String(possible) + '\n');
